import { simpleGit, SimpleGit } from 'simple-git';

export function git(cwd?: string): SimpleGit {
  return simpleGit({ baseDir: cwd });
}

export async function ensureRepo(cwd?: string): Promise<SimpleGit> {
  const client = git(cwd);
  const isRepo = await client.checkIsRepo();
  if (!isRepo) {
    throw new Error('Not a git repository. Run this command inside a git repo.');
  }
  return client;
}

export async function getCurrentBranch(repo?: string) {
  const status = await git(repo).status();
  return status.current;
}

export async function getStagedFiles(repo?: string) {
  const diffSummary = await git(repo).diffSummary(['--cached']);
  return diffSummary.files.map(f => f.file);
}

export async function hasConflicts(repo?: string) {
  const status = await git(repo).status();
  return status.conflicted.length > 0;
}

export async function warnProtectedBranch() {
  const branch = await getCurrentBranch();
  const protectedBranches = ['main', 'master', 'release'];
  if (branch && (protectedBranches.includes(branch) || branch.startsWith('release/'))) {
    console.log('⚠️  You are on a protected branch:', branch);
  }
}
